const responseBody = $input.first().json;
const reqInfo = $('Intent Classifier & Guardrail').first().json;

let parsed = null;
try {
  const rawContent = responseBody.message?.content || '{}';
  parsed = JSON.parse(rawContent);
} catch (e) {
  parsed = {
    verdict: 'CONDITIONAL',
    verdictTitle: 'Phán quyết trọng tài MTG',
    summary: 'Đã phân tích tình huống theo luật MTG Comprehensive Rules.',
    stackSteps: [],
    crRules: [],
    cardNames: []
  };
}

return [{
  json: {
    id: reqInfo.id,
    query: reqInfo.question,
    verdict: parsed.verdict || 'CONDITIONAL',
    verdictTitle: parsed.verdictTitle || 'Phán quyết trọng tài MTG',
    summary: parsed.summary || 'Đã phân tích tương tác theo luật MTG.',
    stackSteps: parsed.stackSteps || [],
    crRules: parsed.crRules || [],
    cardNames: parsed.cardNames || parsed.relatedCards || [],
    isCached: false
  }
}];
